const buyers = $('Buyer Record Search').all();
const deals = $('Deals Search').all();

const results = [];

// Convert Airtable linked-record fields into arrays
function toArray(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    return [value.trim()];
  }
  return [];
}

// Convert dates into timestamps for sorting
function getTimestamp(value) {
  if (!value) return 0;
  const timestamp = Date.parse(value);
  return Number.isNaN(timestamp) ? 0 : timestamp;
}

// Process each buyer
for (const buyerItem of buyers) {
  const buyer = buyerItem.json;

  const buyerMetros = toArray(buyer['Preferred Regions']);

  // Skip buyers without a valid record ID or metro preference
  if (!buyer.id || buyerMetros.length === 0) {
    continue;
  }

  const matchingDeals = [];
  const seenDealIds = new Set();

  // Find all available deals matching this buyer's metros
  for (const dealItem of deals) {
    const deal = dealItem.json;

    if (!deal.id || deal['Listing Status'] !== 'Available') {
      continue;
    }

    // Avoid duplicate property records
    if (seenDealIds.has(deal.id)) {
      continue;
    }

    const dealMetros = toArray(deal['Region IDs']);

    // Exact Airtable Region IDs ID matching
    const matchedMetroId = buyerMetros.find(
      metroId => dealMetros.includes(metroId)
    );

    if (!matchedMetroId) {
      continue;
    }

    seenDealIds.add(deal.id);

    matchingDeals.push({
      dealId: deal.id,
      city: deal.City || null,
      metro: deal['Region Name'] || [],
      matchedMetroId: matchedMetroId,

      dealSummary:
        deal['Listing Headline'] || null,

      marketingSnippet:
        deal['Listing Description'] || null,

      entryFee: deal['Participation Fee'] ?? null,

      priorityScore:
        Number(deal['Ranking Score']) || 0,

      addedDate:
        deal['Listing Added Date'] ||
        deal.createdTime ||
        null
    });
  }

  // Sort: highest priority score, then newest deal
  matchingDeals.sort((a, b) => {
    if (b.priorityScore !== a.priorityScore) {
      return b.priorityScore - a.priorityScore;
    }

    return (
      getTimestamp(b.addedDate) -
      getTimestamp(a.addedDate)
    );
  });

  // Select a maximum of 3 deals
  const topDeals = matchingDeals
    .slice(0, 3)
    .map((deal, index) => ({
      rank: index + 1,
      ...deal
    }));

  // Only return buyers who have matching properties
  if (topDeals.length > 0) {
    results.push({
      json: {
        buyerId: buyer.id,
        buyerName: buyer['Contact Name'] || null,
        phone: buyer['Contact Number'] || null,

        totalMatchingDeals: matchingDeals.length,
        selectedDealCount: topDeals.length,

        topDeals: topDeals,

        // Preparation only; no call is initiated here
        outreachStatus: 'Pending Review'
      }
    });
  }
}

return results;

const matchedBuyers = $('Match Buyers to Deals').all();

const results = [];

// Convert values into safe strings
function cleanText(value) {
  if (value === null || value === undefined) {
    return '';
  }

  if (Array.isArray(value)) {
    return value.filter(Boolean).join(', ');
  }

  return String(value).trim();
}

// Format monetary values for voice conversations
function formatMoney(value) {
  if (value === null || value === undefined || value === '') {
    return 'Not specified';
  }

  const number = Number(value);

  if (!Number.isFinite(number)) {
    return cleanText(value);
  }

  return '$' + number.toLocaleString('en-US', {
    maximumFractionDigits: 0
  });
}

// Process each buyer
for (const item of matchedBuyers) {
  const buyer = item.json;

  const topDeals = Array.isArray(buyer.topDeals)
    ? buyer.topDeals.slice(0, 3)
    : [];

  if (topDeals.length === 0) {
    continue;
  }

  // Format the three deals for NEXUS
  const properties = topDeals.map((deal, index) => ({
    rank: index + 1,
    dealId: deal.dealId,
    matchedMetroId: deal.matchedMetroId,
    city: cleanText(deal.city),
    metro: cleanText(deal.metro),
    summary: cleanText(deal.dealSummary),
    description: cleanText(deal.marketingSnippet),
    entryFee: deal.entryFee ?? null,
    entryFeeFormatted: formatMoney(deal.entryFee)
  }));

  const primaryProperty = properties[0];

  const alternativeProperties = properties.slice(1);

  // Prepare a readable property briefing for the AI agent
  const propertyBriefing = properties.map(property => {
    return [
      `Property ${property.rank}`,
      `Deal ID: ${property.dealId}`,
      `City: ${property.city}`,
      `Metro: ${property.metro}`,
      `Summary: ${property.summary}`,
      `Participation Fee: ${property.entryFeeFormatted}`,
      `Details: ${property.description}`
    ].join('\n');
  }).join('\n\n');

  // Instructions that can be supplied to the Vapi assistant
  const agentInstructions = `
You are PROPERTY ASSISTANT, the AI voice assistant for Example Property Company.

You are speaking with ${cleanText(buyer.buyerName)}.

Your purpose is to discuss available real estate investment
opportunities that match the buyer's preferred metro areas.

CONVERSATION RULES:

1. Introduce yourself as PROPERTY ASSISTANT from Example Property Company.
2. Explain that you are an AI assistant.
3. Ask whether this is a convenient time to discuss a property.
4. Begin with Property 1 only if the buyer agrees.
5. Describe the property naturally and concisely.
6. Ask whether the buyer is interested.
7. If interested, capture the exact Deal ID and request
   a follow-up from the property team.
8. If not interested, ask whether the buyer would like
   to hear about another opportunity.
9. If the buyer agrees, discuss Property 2, then Property 3.
10. Never automatically pitch every property.
11. Never invent prices, property specifications,
    availability, or financing terms.
12. If the buyer declines further discussion, end politely.
13. If the buyer asks not to be contacted again,
    acknowledge the request and flag it for suppression.
14. Do not promise that a deal is reserved or guaranteed.
15. Follow the configured call-recording disclosure
    and company policies.

AVAILABLE PROPERTIES:

${propertyBriefing}
`.trim();

  results.push({
    json: {
      buyerId: buyer.buyerId,
      buyerName: cleanText(buyer.buyerName),
      phone: cleanText(buyer.phone),

      totalMatchingDeals: buyer.totalMatchingDeals,
      selectedDealCount: properties.length,

      primaryProperty,
      alternativeProperties,
      topDeals: properties,

      propertyBriefing,
      agentInstructions,

      // Preparation status only
      outreachStatus: 'Pending Review'
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const buyer = item.json;

  // Remove spaces, brackets, dashes, and other formatting
  let digits = String(buyer.phone || '').replace(/\D/g, '');

  // Convert US 10-digit numbers to international format
  if (digits.length === 10) {
    digits = '1' + digits;
  }

  // Accept US numbers with a country code
  if (!/^1[2-9]\d{2}[2-9]\d{6}$/.test(digits)) {
    continue;
  }

  results.push({
    json: {
      ...buyer,
      phone: '+' + digits
    }
  });
}

return results;
